{"content":"import 'package:mad_flutter_practicum/app/app.dart';
import 'package:mad_flutter_practicum/domain/domain.dart';

import 'widgets/widgets.dart';

class CurrencyListPage extends StatefulWidget {
  const CurrencyListPage({super.key});

  @override
  State<CurrencyListPage> createState() => _CurrencyListPageState();
}

class _CurrencyListPageState extends State<CurrencyListPage> with SingleTickerProviderStateMixin {
  late final ValueNotifier<List<CurrencyModel>> _filteredCurrenciesNotifier;

  late final AnimationController _fadeController;

  late Future<List<CurrencyModel>> _currencyListFuture;

  bool _isLoadingMore = false;
  int _currentPage = 0;
  bool _hasMore = true;
  String _searchQuery = '';

  @override
  void initState() {
    super.initState();
    _initAnimation();
    _initData();
  }

  @override
  void dispose() {
    _filteredCurrenciesNotifier.dispose();
    _fadeController.dispose();
    super.dispose();
  }

  void _resetPagination() {
    _currentPage = 0;
    _hasMore = true;
    _isLoadingMore = false;
  }

  void _initAnimation() {
    _fadeController = AnimationController(
      duration: Duration(milliseconds: 400),
      vsync: this,
    );
  }

  List<CurrencyModel> _allCurrencies = [];

  void _initData() {
    final currencyRepository = context.read<CurrencyRepository>();

    _currencyListFuture = currencyRepository.fetchRates(CurrencyPageRequest(base: 'USD', page: 0, pageSize: 20)).then((CurrencyPage page) {
      final List<CurrencyModel> value = page.items;
      _allCurrencies = value;
      _filteredCurrenciesNotifier = ValueNotifier(value);

      _currentPage = 0;
      _hasMore = page.hasMore;

      _fadeController.forward(); // запускаем анимацию

      currencyRepository.saveCurrencyList(value);

      return value;
    });
  }

  void _filterCurrencies(String query) {
    _searchQuery = query;

    if (_searchQuery.isEmpty) {
      // Очищаем поиск — показываем все загруженные элементы без фильтрации
      _filteredCurrenciesNotifier.value = List.from(_allCurrencies);
    } else {
      final String lowerQuery = query.toLowerCase();
      final Iterable<CurrencyModel> result = _allCurrencies.where((CurrencyModel currency) {
        return currency.name.toLowerCase().contains(lowerQuery) || currency.symbol.toLowerCase().contains(lowerQuery);
      });

      _filteredCurrenciesNotifier.value = result.toList(growable: false);
    }
  }

  void _loadMore() async {
    if (_isLoadingMore || !_hasMore || _searchQuery.isNotEmpty) return;

    setState(() => _isLoadingMore = true);

    final currencyRepository = context.read<CurrencyRepository>();
    _currentPage++;
    try {
      final page = await currencyRepository.fetchRates(CurrencyPageRequest(base: 'USD', page: _currentPage, pageSize: 20));
      _allCurrencies.addAll(page.items);
      _hasMore = page.hasMore;

      // Применяем текущий фильтр к новым элементам
      if (_searchQuery.isNotEmpty) {
        final String lowerQuery = _searchQuery.toLowerCase();
        final List<CurrencyModel> newItems = page.items.where((c) {
          return c.name.toLowerCase().contains(lowerQuery) || c.symbol.toLowerCase().contains(lowerQuery);
        }).toList();

        final currentList = List<CurrencyModel>.from(_filteredCurrenciesNotifier.value)..addAll(newItems);
        _filteredCurrenciesNotifier.value = currentList;
      } else {
        _filteredCurrenciesNotifier.value = List.from(_allCurrencies);
      }
    } catch (_) {
      // при ошибке откатываем номер страницы
      _currentPage--;
    } finally {
      setState(() => _isLoadingMore = false);
    }
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: Text(context.loc.currencyRate)),
      body: FutureBuilder(
        future: _currencyListFuture,
        builder: (BuildContext context, AsyncSnapshot<List<CurrencyModel>> snapshot) {
          final List<CurrencyModel>? data = snapshot.data;
          if (data == null) return const SizedBox.shrink();

          return FadeTransition(
            opacity: _fadeController.view,
            child: Column(
              children: [
                Padding(
                  padding: const EdgeInsets.symmetric(vertical: 10, horizontal: 22),
                  child: SearchView(onChanged: _filterCurrencies),
                ),
                Expanded(
                  child: ValueListenableBuilder<List<CurrencyModel>>(
                    valueListenable: _filteredCurrenciesNotifier,
                    builder: (BuildContext context, List<CurrencyModel> listData, _) {
                      return ListView.builder(
                        itemCount: listData.length + (_hasMore && _searchQuery.isEmpty ? 1 : 0),
                        itemBuilder: (BuildContext context, int index) {
                          if (index == listData.length) {
                            // Индикатор «Показать ещё» внизу списка
                            return Padding(
                              padding: const EdgeInsets.only(bottom: 30.0),
                              child: Center(
                                child: ElevatedButton(
                                  onPressed: _isLoadingMore ? null : _loadMore,
                                  child: _isLoadingMore
                                      ? const SizedBox(
                                          width: 20,
                                          height: 20,
                                          child: CircularProgressIndicator(strokeWidth: 2),
                                        )
                                      : Text(context.loc.showMore),
                                ),
                              ),
                            );
                          }

                          final CurrencyModel currency = listData[index];

                          return Padding(
                            key: ValueKey(currency.id),
                            padding: index == 0 ? const EdgeInsets.only(top: 20) : const EdgeInsets.only(top: 10),
                            child: CurrencyCard(model: currency),
                          );
                        },
                        padding: const EdgeInsets.fromLTRB(22, 0, 22, 40),
                      );
                    },
                  ),
                ),
              ],
            ),
          );
        },
      ),
    );
  }
}
